import CurrentLocation from './CurrentLocation';

import {
    setPlaceholderText,
    addSpinner,
    displayErr,
    displayApiErr,
    toProperCase,
    updateWeatherLocationHeader,
    updateScreenReaderConfirmation,
    updateDisplay
} from './domFunctions';

import {
    setLocationObj,
    getHomeLocation,
    getWeatherFromCoords,
    cleanText,
    getCoordsFromApi
} from './dataFunctions'

const currentLoc = new CurrentLocation()


const initApp = () => {

    // Add Listeners
    const geoBtn = document.querySelector('#nav__link--location');
    geoBtn.addEventListener('click', getGeoWeather);

    const homeBtn = document.querySelector('#nav__link--home');
    homeBtn.addEventListener('click', loadWeather);

    const saveBtn = document.querySelector('#nav__link--save-location');
    saveBtn.addEventListener('click', saveLocation);

    const unitBtn = document.querySelector('#nav__link--unit');
    unitBtn.addEventListener('click', setUnitPref)

    const refreshBtn = document.querySelector('#nav__link--refresh');
    refreshBtn.addEventListener('click', refreshWeather)

    const locationEntry = document.querySelector('#searchBar__form');
    locationEntry.addEventListener('submit', submitNewLocation)

    // Set up
    setPlaceholderText();


    // Load Weather
    loadWeather()
}

document.addEventListener('DOMContentLoaded', initApp)

const updateDataAndDisplay = async (locationObj) => {
    const weatherJson = await getWeatherFromCoords(locationObj)

    if (weatherJson) {
        updateDisplay(weatherJson, locationObj)
    }
}


const getGeoWeather = (e) => {
    if (e) {
        if (e.type === 'click') {
            // add spinner
            const mapIcon = document.querySelector('.fa-map-marker-alt');
            addSpinner(mapIcon)
        }
    }
    if (!navigator.geolocation) {
        return GeolocationPositionError()
    }
    navigator.geolocation.getCurrentPosition(geoSuccess, geoError)
}

const geoSuccess = (position) => {
    const myCoordsObj = {
        lat: position.coords.latitude,
        lon: position.coords.longitude,
        name: `Lat: ${position.coords.latitude}  Long: ${position.coords.longitude}`,
    };

    // set location Obj
    setLocationObj(currentLoc, myCoordsObj);

    // update data and display 
    updateDataAndDisplay(currentLoc);
}

const geoError = (errObj) => {
    const errMsg = errObj ? errObj.Msg : 'Geolocation not supported';
    displayErr(errMsg, errMsg);
}


const loadWeather = (event) => {
    const savedLocation = getHomeLocation();

    if (!savedLocation && !event) {
        return getGeoWeather();
    }
    if (!savedLocation && event.type === 'click') {
        displayErr('No home Location Saved', 'Sorry,Please save your home location first ')
    } else if (savedLocation && !event) {
        displayHomeLocationWeather(savedLocation)
    } else if (savedLocation && event) {
        const homeIcon = document.querySelector('.fa-home');
        addSpinner(homeIcon);
        displayHomeLocationWeather(savedLocation)
    }
}

const displayHomeLocationWeather = (homeLocation) => {
    if (typeof homeLocation === 'string') {
        const locationJson = JSON.parse(homeLocation);

        const myCoordsObj = {
            lat: locationJson.lat,
            lon: locationJson.lon,
            name: locationJson.name,
            unit: locationJson.unit
        }

        setLocationObj(currentLoc, myCoordsObj)
        updateDataAndDisplay(currentLoc)
    };
}


const saveLocation = () => {
    if (currentLoc.getLat() && currentLoc.getLon()) {
        const saveIcon = document.querySelector('.fa-save');
        addSpinner(saveIcon)

        const locationObj = {
            name: currentLoc.getName(),
            lat: currentLoc.getLat(),
            lon: currentLoc.getLon(),
            unit: currentLoc.getUnit()
        }

        localStorage.setItem('defaultWeatherLocation', JSON.stringify(locationObj))
        updateScreenReaderConfirmation(`Saved ${currentLoc.getName()} as home location.`)
    }
}


const setUnitPref = () => {
    const unitIcon = document.querySelector('.fa-chart-bar');
    addSpinner(unitIcon);
    currentLoc.toggleUnit();

    updateDataAndDisplay(currentLoc);
}


const refreshWeather = () => {
    const refreshIcon = document.querySelector('.fa-sync-alt');
    addSpinner(refreshIcon);
    updateDataAndDisplay(currentLoc);
}


const submitNewLocation = async (event) => {
    event.preventDefault()

    const text = document.querySelector('#searchBar__input').value;
    const entryText = cleanText(text);

    if (!entryText) return;

    const locationIcon = document.querySelector('.fa-magnifying-glass');
    addSpinner(locationIcon)
    const coordsData = await getCoordsFromApi(entryText, currentLoc.getUnit())

    console.log(currentLoc);

    if (coordsData) {
        if (coordsData.cod === 200) {
            // work with api data
            // success
            const myCoordsObj = {
                lat: coordsData.coord.lat,
                lon: coordsData.coord.lon,
                name: coordsData.sys.country ? `${coordsData.name},${coordsData.sys.country}` : coordsData.name,

            }

            setLocationObj(currentLoc, myCoordsObj)
            updateDataAndDisplay(currentLoc)
        } else {
            displayApiErr(coordsData)
        }
    } else {
        displayErr("Connection Error", "Connection Error")
    }


}